 void AfterDraw()
 {
  if(pendingFrame<0||sim==null)return;
  var actor=Field<Node3D[]>("_visuals")[sim.PlayerId.Index];if(actor==null)return;
  var rows=new List<object>();
  void Walk(Node node)
  {
   if(node is BoneAttachment3D attachment)
   {
    var skeleton=attachment.GetSkeleton();int bone=attachment.BoneIdx;
    if(skeleton!=null&&bone>=0)
    {
     var expected=skeleton.GlobalTransform*skeleton.GetBoneGlobalPose(bone);var actual=attachment.GlobalTransform;
     rows.Add(new{name=attachment.Name.ToString(),bone=skeleton.GetBoneName(bone),overridePose=attachment.OverridePose,positionError=(actual.Origin-expected.Origin).Length(),basisError=(actual.Basis.X-expected.Basis.X).Length()+(actual.Basis.Y-expected.Basis.Y).Length()+(actual.Basis.Z-expected.Basis.Z).Length(),actual=T(actual),expected=T(expected)});
    }
   }
   foreach(Node child in node.GetChildren())Walk(child);
  }
  Walk(actor);attachments.AppendLine(JsonSerializer.Serialize(new{frame=pendingFrame,note="FramePostDraw evaluated attachment transforms, not pre-render samples",rows},J));
 }
 void Finish(){ready=false;if(ControlledGaitDrill.Clip=="Backpedal"||ControlledGaitDrill.Clip=="StrafeR"||ControlledGaitDrill.Clip=="StrafeL")File.WriteAllText(folder+"/boot-geometry.jsonl",bootGeometry.ToString());File.WriteAllText(folder+"/locomotion.jsonl",locomotion.ToString());File.WriteAllText(folder+"/attachments.jsonl",attachments.ToString());File.WriteAllText(folder+"/sole.jsonl",soles.ToString());File.WriteAllText(folder+"/motion.jsonl",motion.ToString());File.WriteAllText(folder+"/authority.jsonl",authority.ToString());File.WriteAllText(folder+"/camera.tsv",cameras.ToString());File.WriteAllText(folder+"/pose.tsv",poses.ToString());File.WriteAllText(folder+"/summary.json",JsonSerializer.Serialize(new{hero,candidate=ControlledGaitDrill.DisplacementRun,gait=ControlledGaitDrill.Clip,fixedYaw=ControlledGaitDrill.Yaw,updates=sim.Tick,frame,phase=sim.Phase.ToString(),rules=GameSimulation.CheckpointRulesVersion,note="CONTROLLED ASSET DRILL, not normal combat or heading controller. Fresh rule3 crit1030; idle30/full screen-left120/idle30; identical fixed cosmetic heading A/B, original camera/scale/speed, death stops. A in-place selected gait on accepted static rig, B actual-render-displacement stance/flight selected gait on SAME rig; travel direction and anatomical facing are distinct for Backpedal. Run/Backpedal: four alternating footfalls/sec. StrafeR/StrafeL: four synchronized two-foot side-hop landings/sec, not alternating side steps. At 4.8, 50ms stance and 200ms flight. No Core jump/root-motion or static-proportion edit. Body dynamic crouch and hop are cosmetic. Existing natural attacks retained. No HP/enemy/cadence edits."},J));GD.Print($"CONTROLLED_GAIT_MOVIE_DONE hero={hero} updates={sim.Tick} frames={frame} phase={sim.Phase}");GetTree().Quit();}
